    /** FNV-1a 32 位哈希 */
    private static int hash(char[] buf, int len) {
        int h = 0x811C9DC5;
        for (int i = 0; i < len; i++) {
            h ^= buf[i];
            h *= 0x01000193;
        }
        return h;
    }

    private static void put(String key, int type) {
        int index = hash(key.toCharArray(), key.length()) & (SIZE - 1);
        while (KEYS[index] != null) {
            if (KEYS[index].equals(key)) {
                return; // 重复定义，保留先注册的
            }
            index = (index + 1) & (SIZE - 1);
        }
        KEYS[index] = key;
        TYPES[index] = type;
    }

    /**
     * 按归一化后的文本查找 Token 类型，未找到返回 0。
     *
     * @param buf 已按 {@link CharUtil#StandardChar(char)} 归一化的字符
     */
    static int find(char[] buf, int len) {
        int index = hash(buf, len) & (SIZE - 1);
        while (true) {
            String key = KEYS[index];
            if (key == null) {
                return 0;
            }
            if (key.length() == len && regionEquals(key, buf, len)) {
                return TYPES[index];
            }
            index = (index + 1) & (SIZE - 1);
        }
    }

    private static boolean regionEquals(String key, char[] buf, int len) {
        for (int i = 0; i < len; i++) {
            if (key.charAt(i) != buf[i]) {
                return false;
            }
        }
        return true;
    }
